// ΓöÇΓöÇΓöÇ Initial Database (loaded from Azure SQL) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export default function App() {
  // ΓöÇΓöÇ Session States (Persisted) ΓöÇΓöÇ
  const initialRole = localStorage.getItem('userRole') || null
  const initialScreen = initialRole ? 
    (initialRole === 'customer' ? 'home' : 
     initialRole === 'stall' ? 'stall-dashboard' : 
     initialRole === 'rider' ? 'rider-dashboard' : 
     initialRole === 'admin' ? 'admin-dashboard' : 
     initialRole === 'game manager' ? 'games-admin' : 'splash')
    : 'splash'

  const [screen,  setScreen]  = useState(initialScreen)
  const [history, setHistory] = useState([])
  const [userRole, setUserRole] = useState(initialRole) // 'customer' | 'stall' | 'rider' | 'admin' | 'game manager'

  // ΓöÇΓöÇ Database States (synced with Azure SQL) ΓöÇΓöÇ
  const [customers,   setCustomers]   = useState([])
  const [stalls,      setStalls]      = useState([])
  const [staff,       setStaff]       = useState([])
  const [riders,      setRiders]      = useState([])
  const [foods,       setFoods]       = useState([])
  const [orders,      setOrders]      = useState([])
  const [promotions,  setPromotions]  = useState([])
  const [gameManagers,setGameManagers]  = useState([])
  const [dbLoaded,    setDbLoaded]    = useState(false)

  // ΓöÇΓöÇ Load all data from Azure on startup ΓöÇΓöÇ
  // ΓöÇΓöÇ Session States (Persisted) ΓöÇΓöÇ
  const [currentCustomer, setCurrentCustomer] = useState(() => JSON.parse(localStorage.getItem('currentCustomer')) || null)
  const [currentStall,    setCurrentStall]    = useState(() => JSON.parse(localStorage.getItem('currentStall')) || null)
  const [currentRider,    setCurrentRider]    = useState(() => JSON.parse(localStorage.getItem('currentRider')) || null)
  const [currentStallId,  setCurrentStallId]  = useState(() => localStorage.getItem('currentStallId') || null)
  const [currentTrackingOrder, setCurrentTrackingOrder] = useState(() => JSON.parse(localStorage.getItem('currentTrackingOrder')) || null)
  const [cartItems, setCartItems] = useState(() => JSON.parse(localStorage.getItem('cartItems')) || [])
  const [pendingPaymentDetails, setPendingPaymentDetails] = useState(null)

  // Persist session state changes to localStorage
  useEffect(() => { localStorage.setItem('currentCustomer', JSON.stringify(currentCustomer)) }, [currentCustomer])
  useEffect(() => { localStorage.setItem('currentStall', JSON.stringify(currentStall)) }, [currentStall])
  useEffect(() => { localStorage.setItem('currentRider', JSON.stringify(currentRider)) }, [currentRider])
  useEffect(() => { localStorage.setItem('currentStallId', currentStallId || '') }, [currentStallId])
  useEffect(() => { localStorage.setItem('currentTrackingOrder', JSON.stringify(currentTrackingOrder)) }, [currentTrackingOrder])
  useEffect(() => { localStorage.setItem('cartItems', JSON.stringify(cartItems)) }, [cartItems])
  useEffect(() => { if (userRole) { localStorage.setItem('userRole', userRole) } else { localStorage.removeItem('userRole') } }, [userRole])

  // ΓöÇΓöÇ Load all data from Azure on startup ΓöÇΓöÇ
  useEffect(() => {
    // We use Real-time Listeners now instead of get()
    const unsubs = [];
    unsubs.push(api.subscribeCustomers(c => { setCustomers(c) }))
    unsubs.push(api.subscribeStalls(s => { setStalls(s) }))
    unsubs.push(api.subscribeRiders(r => { setRiders(r) }))
    unsubs.push(api.subscribeFoods(f => { setFoods(f) }))
    unsubs.push(api.subscribePromotions(p => { setPromotions(p) }))

    // Setup Audio Ringing for Stalls
    let initialLoad = true;
    unsubs.push(api.subscribeOrders(o => {
      setOrders(prev => {
        // If there's a new order and we are logged in as a stall, play a sound
        if (!initialLoad && currentStall && o.length > prev.length) {
          const latestOrder = o[o.length - 1];
          if (latestOrder.stall_id === currentStall.id && latestOrder.status === 'Pending') {
            try {
              const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2869/2869-preview.mp3');
              audio.play();
            } catch (e) {}
          }
        }
        return o;
      })
      initialLoad = false;
    }))

    // Game Managers doesn't have subscribe yet, so fetch once
    api.getGameManagers().then(gm => {
      setGameManagers(gm)
      setDbLoaded(true)
    }).catch(err => {
      console.warn('ΓÜá∩╕Å Could not load GameManagers:', err.message)
      setDbLoaded(true)
    })

    return () => unsubs.forEach(unsub => unsub && unsub());
  }, [currentStall])

  // ΓöÇΓöÇ Navigation ΓöÇΓöÇ
  const nav  = (s) => { setHistory(h => [...h, screen]); setScreen(s) }
  const goTo = (s) => { setHistory([]); setScreen(s) }
  const back = ()  => { const h = [...history]; const prev = h.pop() || 'home'; setHistory(h); setScreen(prev) }

  // ΓöÇΓöÇ Cart ΓöÇΓöÇ
  const addToCart = (item) => {
    setCartItems(prev => {
      const ex = prev.find(i => i.id === item.id)
      if (ex) return prev.map(i => i.id === item.id ? { ...i, qty: i.qty + 1 } : i)
      return [...prev, { ...item, qty: 1 }]
    })
  }

  const updateQty = (id, d) => {
    setCartItems(prev =>
      prev.map(i => i.id === id ? { ...i, qty: Math.max(0, i.qty + d) } : i).filter(i => i.qty > 0)
    )
  }

  // ΓöÇΓöÇ Auth Handlers ΓöÇΓöÇ
  const handleCustomerLogin = (customerObj) => {
    setUserRole('customer')
    setCurrentCustomer(customerObj)
    goTo('home')
  }

  const handleStallLogin = (stallObj) => {
    setUserRole('stall')
    setCurrentStall(stallObj)
    goTo('stall-dashboard')
  }

  const handleRiderLogin = (riderObj) => {
    setUserRole('rider')
    setCurrentRider(riderObj)
    goTo('rider-dashboard')
  }

  const handleAdminLogin = () => {
    setUserRole('admin')
    goTo('admin-dashboard')
  }

  const handleGamesLogin = () => {
    setUserRole('game manager')
    goTo('games-admin')
  }

  const handleLogout = () => {
    localStorage.clear()
    setUserRole(null)
    setCurrentCustomer(null)
    setCurrentStall(null)
    setCurrentRider(null)
    setCurrentStallId(null)
    setCurrentTrackingOrder(null)
    setCartItems([])
    setHistory([])
    setScreen('getstarted')
  }

  // ΓöÇΓöÇ Multi-Stall Order Splitter ΓöÇΓöÇ
  // Takes the unified cart and splits into one order per stall,
  // all linked by a shared group_id for the rider to pick up together.
  const handlePlaceOrder = (details) => {
    if (cartItems.length === 0) return

    // Block guest users from placing orders
    if (!currentCustomer || currentCustomer.id === 0) {
      alert('Please login or register to place an order.')
      return
    }

    if (details.paymentMethod !== 'Cash on Delivery') {
      setPendingPaymentDetails(details)
      return
    }

    finalizeOrder(details)
  }

  const finalizeOrder = async (details) => {
    const groupId = `G${Math.floor(10000 + Math.random() * 90000)}`
    const timestamp = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })

    // Group cart items by stall_id
    const byStall = {}
    cartItems.forEach(item => {
      const sId = item.stall_id
      if (!sId) return // Skip items without a stall_id
      if (!byStall[sId]) byStall[sId] = []
      byStall[sId].push(item)
    })

    const newOrdersPromises = Object.keys(byStall).map(async stallIdStr => {
      const stallId = isNaN(Number(stallIdStr)) ? stallIdStr : Number(stallIdStr)
      const stallItems = byStall[stallIdStr]
      const itemsSummary = stallItems.map(i => `${i.qty}x ${i.food_name || i.name}`).join(', ')
      const stallTotal = stallItems.reduce((s, i) => s + i.price * i.qty, 0)
      const stallNote = details.notes?.[stallId] || details.notes || ''

      const newOrderData = {
        customer_id: currentCustomer?.id,
        stall_id: stallId,
        rider_id: null,         // Assigned later when a Rider accepts
        group_id: groupId,      // Links all sub-orders in this checkout
        total_price: stallTotal,
        status: 'Pending',
        payment_method: details.paymentMethod,
        items: itemsSummary,
        notes: stallNote,
        time: timestamp,
      }

      try {
        const savedOrder = await api.addOrder(newOrderData)
        return savedOrder
      } catch (err) {
        console.error('Failed to save order to Firebase:', err)
        // Fallback to local order if offline
        return { id: Math.floor(10000 + Math.random() * 90000).toString(), ...newOrderData }
      }
    })

    const savedOrders = await Promise.all(newOrdersPromises)

    // Also create a "virtual" master order object for the tracking screen
    const masterOrder = {
      id: groupId,
      group_id: groupId,
      customer_id: currentCustomer?.id,
      total_price: details.totalPrice,
      payment_method: details.paymentMethod,
      status: 'Pending',
      time: timestamp,
    }

    setOrders(prev => [...prev, ...savedOrders])
    setCartItems([])
    setCurrentTrackingOrder(masterOrder)
    nav('tracking')
  }

  const handleUpdateProfile = async (updatedCust) => {
    try {
      const saved = await api.updateCustomer(updatedCust.id, updatedCust)
      setCustomers(prev => prev.map(c => c.id === saved.id ? saved : c))
      setCurrentCustomer(saved)
    } catch (err) {
      // Fallback to local update if API fails
      setCustomers(prev => prev.map(c => c.id === updatedCust.id ? updatedCust : c))
      setCurrentCustomer(updatedCust)
    }
  }

  const handleUpdateStallProfile = async (updatedStall) => {
    try {
      const saved = await api.updateStall(updatedStall.id, updatedStall)
      setStalls(prev => prev.map(s => s.id === saved.id ? saved : s))
      setCurrentStall(saved)
    } catch (err) {
      console.error('Failed to update stall profile:', err)
      // Fallback
      setStalls(prev => prev.map(s => s.id === updatedStall.id ? updatedStall : s))
      setCurrentStall(updatedStall)
    }
  }

  // ΓöÇΓöÇ Screen Renderer ΓöÇΓöÇ
  const renderScreen = () => {
    switch (screen) {

      // ΓöÇΓöÇ Onboarding ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      case 'splash':
        return <Splash onStart={() => goTo('getstarted')} />

      case 'getstarted':
        return (
          <GetStarted
            onLogin={() => nav('login')}
            onRegister={() => { nav('login') }}   // Login page has inline register
            onGuest={() => {
              // Guest browsing ΓÇö show home without account
              setUserRole('customer')
              setCurrentCustomer({ id: 0, fullname: 'Guest', phone: '', address: '', status: 'active' })
              goTo('home')
            }}
          />
        )

      case 'login':
        return (
          <Login
            onBack={back}
            onLogin={handleCustomerLogin}
            onStallLogin={handleStallLogin}
            onRiderLogin={handleRiderLogin}
            onAdminLogin={handleAdminLogin}
            onGamesLogin={handleGamesLogin}
            customers={customers}
            stalls={stalls}
            staff={staff}
            riders={riders}
            onRegisterCustomer={async (newCust) => {
              try {
                const saved = await api.addCustomer(newCust)
                setCustomers(prev => [...prev, saved])
                return saved
              } catch (err) {
                throw err;
              }
            }}
            onGuest={() => {
              setUserRole('customer')
              setCurrentCustomer({ id: 0, fullname: 'Guest', phone: '', address: '', status: 'active' })
              goTo('home')
            }}
          />
        )

      // ΓöÇΓöÇ Customer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      case 'home':
        return (
          <Home
            stalls={stalls}
            foods={foods}
            currentCustomer={currentCustomer}
            promos={promotions}
            onRestaurant={(stall) => { setCurrentStallId(stall.id); nav('restaurant') }}
            onSearch={() => nav('search')}
            onPromoOrder={() => nav('search')}
          />
        )

      case 'search':
        return (
          <Search
            stalls={stalls}
            foods={foods}
            onRestaurant={(stall) => { setCurrentStallId(stall.id); nav('restaurant') }}
            onBack={back}
          />
        )

      case 'orders':
        return (
          <Orders
            orders={orders}
            stalls={stalls}
            currentCustomer={currentCustomer}
            onTrack={(order) => { setCurrentTrackingOrder(order); nav('tracking') }}
          />
        )

      case 'offers':
        return <Offers promotions={promotions} />

      case 'games':
        return <Games currentCustomer={currentCustomer} promotions={promotions} />

      case 'games-admin':
        return <Games currentCustomer={currentCustomer} promotions={promotions} initialView="admin" />

      case 'tracking': {
        // Find the right order/group to track
        const trackOrder = currentTrackingOrder
          || orders.find(o => o.customer_id === currentCustomer?.id && o.status === 'Delivering')
          || orders.find(o => o.customer_id === currentCustomer?.id && o.status !== 'Delivered' && o.status !== 'Cancelled')

        return (
          <OrderTracking
            onBack={back}
            order={trackOrder}
            orders={orders}
            setOrders={setOrders}
            stalls={stalls}
            riders={riders}
          />
        )
      }

      case 'account':
        return (
          <Account
            onLogout={handleLogout}
            currentCustomer={currentCustomer}
            onUpdateProfile={handleUpdateProfile}
            orders={orders}
          />
        )

      case 'restaurant':
        return (
          <Restaurant
            stall={stalls.find(s => s.id === currentStallId)}
            foods={foods}
            onBack={back}
            onCart={() => nav('cart')}
            addToCart={addToCart}
            cartItems={cartItems}
            isGuest={currentCustomer?.id === 0}
          />
        )

      case 'cart':
        return (
          <Cart
            items={cartItems}
            updateQty={updateQty}
            onBack={back}
            onShopping={() => goTo('home')}
            onPlaceOrder={handlePlaceOrder}
            stalls={stalls}
            isGuest={currentCustomer?.id === 0}
            onLogin={() => nav('login')}
          />
        )

      // ΓöÇΓöÇ Stall Staff ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      case 'stall-dashboard':
        return (
          <StallDashboard
            onLogout={handleLogout}
            stall={stalls.find(s => s.id === currentStall?.id) || currentStall}
            foods={foods}
            setFoods={setFoods}
            orders={orders}
            setOrders={setOrders}
            customers={customers}
            onUpdateStallProfile={handleUpdateStallProfile}
          />
        )

      // ΓöÇΓöÇ Delivery Rider ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      case 'rider-dashboard':
        return (
          <RiderDashboard
            onLogout={handleLogout}
            rider={currentRider}
            orders={orders}
            setOrders={setOrders}
            stalls={stalls}
            customers={customers}
          />
        )

      // ΓöÇΓöÇ Admin ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      case 'admin-dashboard':
        return (
          <AdminDashboard
            onLogout={handleLogout}
            stalls={stalls}
            setStalls={setStalls}
            customers={customers}
            setCustomers={setCustomers}
            orders={orders}
            promotions={promotions}
            setPromotions={setPromotions}
            staff={staff}
            setStaff={setStaff}
            riders={riders}
            setRiders={setRiders}
            gameManagers={gameManagers}
            setGameManagers={setGameManagers}
          />
        )

      default:
        return <Splash onStart={() => goTo('getstarted')} />
    }
  }

  const showBottomNav = CUSTOMER_SCREENS.includes(screen) && userRole === 'customer'

  // Count active orders for badge on Track tab
  const activeOrderCount = currentCustomer
    ? orders.filter(o => o.customer_id === currentCustomer.id && o.status !== 'Delivered' && o.status !== 'Cancelled').length
    : 0

  return (
    <div className="app-shell">
      <div className="screen-wrap">
        <div className="screen">
          {renderScreen()}
        </div>
        {showBottomNav && (
          <BottomNav
            active={screen}
            onNav={nav}
            cartCount={cartItems.reduce((s,i) => s+i.qty, 0)}
            activeOrderCount={activeOrderCount}
          />
        )}
      </div>

      {pendingPaymentDetails && (
        <PaymentGateway 
          amount={pendingPaymentDetails.totalPrice}
          method={pendingPaymentDetails.paymentMethod}
          onSuccess={() => {
            const details = pendingPaymentDetails
            setPendingPaymentDetails(null)
            finalizeOrder(details)
          }}
          onCancel={() => setPendingPaymentDetails(null)}
        />
      )}
    </div>
  )
}

import { db, auth } from './firebase.js';
import { ref, get, set, push, update, remove, onValue } from 'firebase/database';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';

// Helper to get all items as an array from RTDB
async function fetchAll(pathName) {
  const snapshot = await get(ref(db, pathName));
  if (!snapshot.exists()) return [];
  const data = snapshot.val();
  return Object.keys(data).map(key => ({ id: key, ...data[key] }));
}

// Helper to add an item
async function add(pathName, data) {
  const newRef = push(ref(db, pathName));
  const newDoc = { ...data, created_at: new Date().toISOString() };
  await set(newRef, newDoc);
  return { id: newRef.key, ...newDoc };
}

// Helper to update an item
async function updateItem(pathName, id, data) {
  const itemRef = ref(db, `${pathName}/${id}`);
  await update(itemRef, data);
  return { id, ...data };
}

// Helper to delete an item
async function del(pathName, id) {
  await remove(ref(db, `${pathName}/${id}`));
  return { id };
}

// Helper to subscribe to a path
function subscribe(pathName, callback) {
  return onValue(ref(db, pathName), (snapshot) => {
    if (!snapshot.exists()) {
      callback([]);
      return;
    }
    const data = snapshot.val();
    const arr = Object.keys(data).map(key => ({ id: key, ...data[key] }));
    callback(arr);
  });
}

export const api = {
  // Auth
  login: async (email, password) => {
    // 1. Admin hardcoded
    if ((email === 'admin' || email === 'admin@pobla.go') && password === 'admin')
      return { role: 'admin', user: { fullname: 'Admin', email } };

    // 2. Games Manager hardcoded fallback
    if ((email === 'games' || email === 'games@pobla.go') && password === 'games')
      return { role: 'game-manager', user: { fullname: 'Games Manager', email } };

    const checkPath = async (pathName, role) => {
      const items = await fetchAll(pathName);
      const field = pathName === 'stalls' ? 'username' : 'email';
      const found = items.find(i => i[field]?.toLowerCase() === email.toLowerCase());

      if (found) {
        if (found.status === 'suspended') throw new Error('Account suspended.');
        return { role, user: found, plain_password: found.password };
      }
      return null;
    };

    let record = await checkPath('game_managers', 'game-manager') ||
                 await checkPath('customers', 'customer') ||
                 await checkPath('stalls', 'stall') ||
                 await checkPath('riders', 'rider');

    if (!record) {
      throw new Error('Invalid email or password.');
    }

    try {
      await signInWithEmailAndPassword(auth, email, password);
    } catch (error) {
      // Fallback for old users who haven't been migrated to Firebase Auth yet
      if (error.code === 'auth/user-not-found' || error.code === 'auth/invalid-credential' || error.code === 'auth/invalid-login-credentials' || error.code === 'auth/wrong-password') {
        if (record.plain_password === password) {
          try {
             // Auto-migrate user
             await createUserWithEmailAndPassword(auth, email, password);
          } catch(e) {
             console.error("Firebase Auth migration failed:", e.message);
          }
        } else {
          throw new Error('Invalid email or password.');
        }
      } else {
        throw new Error(error.message);
      }
    }

    return { role: record.role, user: record.user };
  },

  // Customers
  getCustomers: () => fetchAll('customers'),
  subscribeCustomers: (cb) => subscribe('customers', cb),
  addCustomer: async (data) => {
    const items = await fetchAll('customers');
    const exists = items.find(i => i.email?.toLowerCase() === data.email.toLowerCase());
    if (exists) throw new Error('Email already registered.');

    try {
      await createUserWithEmailAndPassword(auth, data.email, data.password);
    } catch (error) {
      throw new Error(error.message);
    }

    return add('customers', data);
  },
  updateCustomer: (id, data) => updateItem('customers', id, data),

  // Stalls
  getStalls: () => fetchAll('stalls'),
  subscribeStalls: (cb) => subscribe('stalls', cb),
  addStall: (data) => add('stalls', data),
  updateStall: (id, data) => updateItem('stalls', id, data),

  // Riders
  getRiders: () => fetchAll('riders'),
  subscribeRiders: (cb) => subscribe('riders', cb),
  addRider: (data) => add('riders', data),
  updateRider: (id, data) => updateItem('riders', id, data),

  // Foods
  getFoods: () => fetchAll('foods'),
  subscribeFoods: (cb) => subscribe('foods', cb),
  addFood: (data) => add('foods', data),
  updateFood: (id, data) => updateItem('foods', id, data),
  deleteFood: (id) => del('foods', id),

  // Orders
  getOrders: () => fetchAll('orders'),
  subscribeOrders: (cb) => subscribe('orders', cb),
  addOrder: (data) => add('orders', data),
  updateOrder: (id, data) => updateItem('orders', id, data),

  // Promotions
  getPromotions: () => fetchAll('promotions'),
  subscribePromotions: (cb) => subscribe('promotions', cb),
  addPromotion: (data) => add('promotions', data),
  deletePromotion: (id) => del('promotions', id),

  // Game Reservations
  getReservations: () => fetchAll('reservations'),
  subscribeReservations: (cb) => subscribe('reservations', cb),
  addReservation: (data) => add('reservations', data),
  updateReservation: (id, data) => updateItem('reservations', id, data),

  // Court Prices
  getCourtPrices: async () => {
    const prices = await fetchAll('court_prices');
    if (prices.length > 0) return prices;
    return [{ morning_rate: 200, afternoon_rate: 280, open_play_rate: 150 }];
  },
  updateCourtPrices: async (data) => {
    const prices = await fetchAll('court_prices');
    if (prices.length > 0) {
      return updateItem('court_prices', prices[0].id, data);
    } else {
      return add('court_prices', data);
    }
  },

  // Game Managers
  getGameManagers: () => fetchAll('game_managers'),
  addGameManager: (data) => add('game_managers', data),
};

import { useState } from 'react'
import './Login.css'

export default function Login({ 
  onBack, 
  onLogin, 
  onStallLogin, 
  onRiderLogin, 
  onAdminLogin, 
  onGamesLogin,
  customers = [], 
  stalls = [], 
  staff = [],
  riders = [], 
  onRegisterCustomer,
  onGuest
}) {
  const [activeTab, setActiveTab] = useState('login')
  const [role, setRole] = useState('customer')
  const [showRoleDropdown, setShowRoleDropdown] = useState(false)
  const [email, setEmail] = useState('')
  const [pass, setPass] = useState('')
  const [show, setShow] = useState(false)
  const [error, setError] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  // Register Fields
  const [regName, setRegName] = useState('')
  const [regEmail, setRegEmail] = useState('')
  const [regPhone, setRegPhone] = useState('')
  const [regAddr, setRegAddr] = useState('')
  const [regPass, setRegPass] = useState('')
  const [regConfirmPass, setRegConfirmPass] = useState('')

  const handleLoginSubmit = (e) => {
    e?.preventDefault?.()
    setError('')

    const user = email.trim()
    const password = pass.trim()

    if (!user || !password) {
      setError('Please enter your email and password.')
      return
    }

    setIsLoading(true)
    setTimeout(() => {
      // 1. Admin Login
    if ((user.toLowerCase() === 'admin' || user.toLowerCase() === 'admin@pobla.go') && password === 'admin') {
      onAdminLogin?.()
      return
    }

    // 2. Games Manager Login
    if ((user.toLowerCase() === 'games' || user.toLowerCase() === 'games@pobla.go') && password === 'games') {
      onGamesLogin?.()
      setIsLoading(false)
      return
    }

    // 3. Customer Login
    const foundCust = customers.find(c => (c.email?.toLowerCase() === user.toLowerCase() || c.phone === user) && c.password === password)
    if (foundCust) {
      if (foundCust.status === 'suspended') {
        setError('This account has been suspended. Contact support.')
        setIsLoading(false)
        return
      }
      onLogin?.(foundCust)
      setIsLoading(false)
      return
    }

    // 4. Stall Login (Staff or Owner)
    const foundStaff = staff.find(s => s.email?.toLowerCase() === user.toLowerCase() && s.password === password)
    const foundStall = stalls.find(s => s.username?.toLowerCase() === user.toLowerCase() && s.password === password)

    if (foundStaff) {
      const stallObj = stalls.find(st => st.id === foundStaff.stall_id)
      if (stallObj?.status === 'suspended') {
        setError('Your stall has been suspended by Admin.')
      } else {
        onStallLogin?.({ ...stallObj, staffName: foundStaff.fullname, staffId: foundStaff.id })
      }
      setIsLoading(false)
      return
    } else if (foundStall) {
