      }
      setIsLoading(false)
      return
    }

    // 5. Rider Login
    const foundRider = riders.find(r => r.email?.toLowerCase() === user.toLowerCase() && r.password === password)
    if (foundRider) {
      if (foundRider.status === 'suspended') {
