          </button>
        ))}
      </div>

      <div className="ord-body">
        {tab === 'active' && renderOrderList(activeOrders)}
        {tab === 'completed' && renderOrderList(completedOrders)}
        {tab === 'cancelled' && renderOrderList(cancelledOrders)}
      </div>
    </div>
  )
}

